N=22
g=[[0]*N for _ in range(N)]
def put(r,c,v):
    if 0<=r<N and 0<=c<N:
        if v!=2 or g[r][c]==0: g[r][c]=v
# fixed 4 shape and markers
for r in range(8,11):
    for c in range(10,13): put(r,c,4)
for r,c in [(7,11),(9,9),(11,10),(11,12)]: put(r,c,2)
# 7 original color and markers translated +5,+3
for r,c in [(3,c) for c in range(2,6)]+[(4,2),(5,2)]+[(6,c) for c in range(2,6)]: put(r+5,c+3,7)
for r,c in [(3,6),(6,6)]: put(r+5,c+3,2)
# 8 translated +10,-6
for r,c in [(2,16)]+[(3,c) for c in range(16,21)]: put(r+10,c-6,8)
for r,c in [(1,16),(1,20)]: put(r+10,c-6,2)
# 3 translated -11,-6
coords=[(13,c) for c in range(14,20)]+[(14,14),(14,19),(15,14),(15,19),(16,14),(17,14)]+[(18,c) for c in range(14,17)]
for r,c in coords: put(r-11,c-6,3)
for r,c in [(14,13),(16,19),(18,17)]: put(r-11,c-6,2)
# 9 translated -9,+11
coords=[(18,3),(18,5),(19,3),(19,5)]+[(20,c) for c in range(2,7)]
for r,c in coords: put(r-9,c+11,9)
for r,c in [(17,3),(17,5),(21,2),(21,6)]: put(r-9,c+11,2)
print('\n'.join(' '.join(map(str,row)) for row in g))
